From bb43d40d7c830da5f623e3938fef908b003b7523 Mon Sep 17 00:00:00 2001
From: Maxime Ripard <maxime.ripard@free-electrons.com>
Date: Thu, 21 Apr 2016 11:25:26 +0200
Subject: [PATCH] drm/sun4i: rgb: Validate the clock rate

Our pixel clock cannot reach a high enough rate for some rather high while
common resolutions (like 1080p60).

Make sure we filter the resolutions we cannot reach in our mode_valid
function.

Fixes: 29e57fab97fc ("drm: sun4i: Add RGB output")
Signed-off-by: Maxime Ripard <maxime.ripard@free-electrons.com>

diff --git a/drivers/gpu/drm/sun4i/sun4i_rgb.c b/drivers/gpu/drm/sun4i/sun4i_rgb.c
index ab6494818050..fe7ef52a9346 100644
--- a/drivers/gpu/drm/sun4i/sun4i_rgb.c
+++ b/drivers/gpu/drm/sun4i/sun4i_rgb.c
@@ -54,8 +54,13 @@ static int sun4i_rgb_get_modes(struct drm_connector *connector)
 static int sun4i_rgb_mode_valid(struct drm_connector *connector,
 				struct drm_display_mode *mode)
 {
+	struct sun4i_rgb *rgb = drm_connector_to_sun4i_rgb(connector);
+	struct sun4i_drv *drv = rgb->drv;
+	struct sun4i_tcon *tcon = drv->tcon;
 	u32 hsync = mode->hsync_end - mode->hsync_start;
 	u32 vsync = mode->vsync_end - mode->vsync_start;
+	unsigned long rate = mode->clock * 1000;
+	long rounded_rate;

 	DRM_DEBUG_DRIVER("Validating modes...\n");

@@ -87,6 +92,15 @@ static int sun4i_rgb_mode_valid(struct drm_connector *connector,

 	DRM_DEBUG_DRIVER("Vertical parameters OK\n");

+	rounded_rate = clk_round_rate(tcon->dclk, rate);
+	if (rounded_rate < rate)
+		return MODE_CLOCK_LOW;
+
+	if (rounded_rate > rate)
+		return MODE_CLOCK_HIGH;
+
+	DRM_DEBUG_DRIVER("Clock rate OK\n");
+
 	return MODE_OK;
 }

-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the inability of the pixel clock to reach the necessary rates for certain high resolutions, such as 1080p60. This results in the driver potentially accepting display modes that cannot be supported by the hardware, leading to display issues. The lack of validation for the clock rate in the `mode_valid` function allows unsupported resolutions to be processed, causing failures in rendering.

        Commit message:
        drm/sun4i: rgb: Validate the clock rate

Our pixel clock cannot reach a high enough rate for some rather high while
common resolutions (like 1080p60).

Make sure we filter the resolutions we cannot reach in our mode_valid
function.

Fixes: 29e57fab97fc ("drm: sun4i: Add RGB output")
Signed-off-by: Maxime Ripard <maxime.ripard@free-electrons.com>  

        Patch:

 static int sun4i_rgb_mode_valid(struct drm_connector *connector,
 				struct drm_display_mode *mode)
 {
+	struct sun4i_rgb *rgb = drm_connector_to_sun4i_rgb(connector);
+	struct sun4i_drv *drv = rgb->drv;
+	struct sun4i_tcon *tcon = drv->tcon;
 	u32 hsync = mode->hsync_end - mode->hsync_start;
 	u32 vsync = mode->vsync_end - mode->vsync_start;
+	unsigned long rate = mode->clock * 1000;
+	long rounded_rate;

 	DRM_DEBUG_DRIVER("Validating modes...\n");

 	if (hsync < 1)
 		return MODE_HSYNC_NARROW;

 	if (hsync > 0x3ff)
 		return MODE_HSYNC_WIDE;

 	if ((mode->hdisplay < 1) || (mode->htotal < 1))
 		return MODE_H_ILLEGAL;

 	if ((mode->hdisplay > 0x7ff) || (mode->htotal > 0xfff))
 		return MODE_BAD_HVALUE;

 	DRM_DEBUG_DRIVER("Horizontal parameters OK\n");

 	if (vsync < 1)
 		return MODE_VSYNC_NARROW;

 	if (vsync > 0x3ff)
 		return MODE_VSYNC_WIDE;

 	if ((mode->vdisplay < 1) || (mode->vtotal < 1))
 		return MODE_V_ILLEGAL;

 	if ((mode->vdisplay > 0x7ff) || (mode->vtotal > 0xfff))
 		return MODE_BAD_VVALUE;

 	DRM_DEBUG_DRIVER("Vertical parameters OK\n");

+	rounded_rate = clk_round_rate(tcon->dclk, rate);
+	if (rounded_rate < rate)
+		return MODE_CLOCK_LOW;
+
+	if (rounded_rate > rate)
+		return MODE_CLOCK_HIGH;
+
+	DRM_DEBUG_DRIVER("Clock rate OK\n");
+
 	return MODE_OK;
 }



